"""The comment this agent posts, rendered in code from the triage result.

The wording is code, not a model turn, so it is testable and a change to it is a
reviewed diff. The calculator's own text comes first, verbatim except for its
"Generated by command line" footer (noise to an engineer): it carries the
permalink and the selections behind the rating, which is what lets an engineer
who disagrees re-triage in one click. Everything after it says what that rating
rests on.
"""

from __future__ import annotations

import re
from dataclasses import asdict

from performance_tools.text import clean as _clean
from performance_tools.triage import TriageResult
from performance_tools.triage.stability import (
    INPUTS,
    Stability,
    args_from_selections,
    input_label,
    value_label,
)

from .hooks import REVIEWER
from .preflight import WriteMode

_GENERATED_BY = re.compile(r"\n*^\*Generated by command line:.*\*$", re.M)

# hackbot_runtime's add_comment appends this to model-written comments; this
# comment is recorded directly, so it is reproduced here.
REACTION_LINE = (
    "If you'd like to provide feedback on this comment, please use the 👍 or 👎 "
    "reaction."
)
FEEDBACK_TAGS = (
    "If you want to categorize your feedback you can add one of the following "
    "tags: perf-triage-{wrong-impact, wrong-component, wrong-cause, "
    "wrong-severity, hallucination, not-perf}."
)


def _inline(text: object) -> str:
    """One line of model text that cannot start a Markdown block or a section.

    Model strings reach a public comment, sometimes unattended. Newlines are what
    let a string open a new block (a heading, a rule, a fake "Existing rating"
    line), so collapse them; then neutralise a leading block marker.
    """
    flat = " ".join(_clean(str(text)).split())
    flat = flat.replace("<", "‹").replace(">", "›")
    return re.sub(r"^[#>\-*+=|`]+\s*", "", flat)


def _assumed(result: TriageResult, name: str) -> str:
    args = asdict(args_from_selections(result.selections))
    key = name.replace("-", "_")
    if key in args:
        return value_label(name, args[key]) or "none"
    return value_label(name, name in args["additional_factors"])


def _basis(result: TriageResult, stability: Stability) -> list[str]:
    names = list(dict.fromkeys(result.unestablished))
    known = [n for n in names if n in INPUTS]
    if not names:
        return []
    lines: list[str] = []
    if known:
        lines.append("Not established by the bug (the rating assumes these values):")
        lines += [f"- {input_label(n)}: {_assumed(result, n)}" for n in known]
    if stability.unknown:
        lines += [
            "",
            "Not a calculator input: "
            + ", ".join(_inline(n) for n in stability.unknown),
        ]
    if not stability.confident and known:
        if stability.flipping:
            changing = ", ".join(input_label(n) for n in stability.flipping)
            lines += ["", f"Would change the rating: {changing}"]
        elif len(stability.bands) > 1:
            together = ", ".join(input_label(n) for n in known)
            lines += ["", f"Would change the rating together: {together}"]
    return lines


def _related(result: TriageResult) -> list[str]:
    if not result.related:
        return []

    # With its value: a bare "Reproduces in Chrome" reads as yes when the related
    # bug established no (2080869, from 2084175's "Chrome is fine").
    def label(n: str) -> str:
        if n not in INPUTS:
            return _inline(n)
        return f"{input_label(n)}: {_assumed(result, n)}"

    return ["Taken from related bugs:"] + [
        f"- Bug {r.bug}: {'; '.join(label(n) for n in r.settled) or 'no inputs named'}"
        for r in result.related
    ]


def _profile(result: TriageResult, current_component: str) -> list[list[str]]:
    p = result.profile
    if p is None:
        return []
    if not p.analysed:
        return [
            [
                f"Profile not analysed: {_inline(p.not_analysed_reason or '') or 'unknown reason'}"
            ]
        ]
    summary = _inline(p.summary or "") or "no summary returned"
    source = p.url or (f"attachment {p.attachment}" if p.attachment else "")
    blocks = [[f"Profile ({_inline(source)}): {summary}"]]
    if p.changed_attributes:
        changed = ", ".join(
            f"{input_label(k)} → {_inline(value_label(k, v))}"
            for k, v in p.changed_attributes.items()
        )
        blocks.append([f"The profile changed: {changed}"])
    component = _inline(p.component or "")
    if (
        result.component is None
        and component
        and component != _inline(current_component)
    ):
        blocks.append(
            [f"Suggested component: {component} (filed in {current_component})"]
        )
    return blocks


def _memory_report(result: TriageResult, current_component: str) -> list[list[str]]:
    m = result.memory_report
    if m is None:
        return []
    summary = _inline(m.summary or "") or "no summary returned"
    blocks = [[f"Memory report (attachment {m.attachment}): {summary}"]]
    if m.changed_attributes:
        changed = ", ".join(
            f"{input_label(k)} → {_inline(value_label(k, v))}"
            for k, v in m.changed_attributes.items()
        )
        blocks.append([f"The memory report changed: {changed}"])
    component = _inline(m.component or "")
    if (
        result.component is None
        and component
        and component != _inline(current_component)
    ):
        blocks.append(
            [f"Suggested component: {component} (filed in {current_component})"]
        )
    return blocks


def _component(result: TriageResult, current_component: str) -> list[str]:
    """One suggestion from the skill's final decision; replaces the per-evidence ones."""
    c = result.component
    if c is None or c.action != "move" or not c.verified:
        return []
    name = _inline(c.name)
    if not name or name == _inline(current_component):
        return []
    return [f"Suggested component: {name} (filed in {current_component})"]


def render_comment(
    result: TriageResult,
    stability: Stability,
    mode: WriteMode,
    *,
    current_component: str,
    existing_impact: str | None,
) -> str:
    """The full comment text, footer included."""
    sections: list[list[str]] = [
        [_GENERATED_BY.sub("", result.comment).strip()],
        _basis(result, stability),
        _related(result),
        *_profile(result, current_component),
        *_memory_report(result, current_component),
        _component(result, current_component),
    ]
    if result.severity:
        sections.append([f"Suggested severity: {result.severity}"])
    if mode == "comment_only":
        sections.append(
            [
                f"Existing rating: **{existing_impact}** · this triage: **{result.impact}**"
            ]
        )
    sections.append([f"Disagree with this assessment? Needinfo {REVIEWER}."])
    body = "\n\n".join("\n".join(s) for s in sections if s)
    return f"{body}\n\n---\n\n{REACTION_LINE}\n{FEEDBACK_TAGS}\n"
